import java.util.*;import java.util.zip.*;import org.objectweb.asm.*;import org.objectweb.asm.tree.*;import org.objectweb.asm.tree.analysis.*;
public class Verify {public static void main(String[]a)throws Exception{int methods=0;try(ZipFile z=new ZipFile(a[0])){for(var e:Collections.list(z.entries()))if(e.getName().endsWith(".class")){if(!e.getName().startsWith("dev/zomboid/gore/"))throw new Exception("Unexpected class "+e);ClassNode c=new ClassNode();new ClassReader(z.getInputStream(e)).accept(c,0);if(c.name.contains("/mixin/")&&(c.invisibleAnnotations==null||c.invisibleAnnotations.stream().noneMatch(x->x.desc.equals("Lorg/spongepowered/asm/mixin/Mixin;"))))throw new Exception("Mixin retention");for(MethodNode m:c.methods)if((m.access&0x500)==0){new Analyzer<>(new BasicVerifier()).analyze(c.name,m);methods++;}}}try(ZipFile z=new ZipFile(a[1])){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry("com/tacz/guns/entity/EntityKineticBullet.class"))).accept(c,0);if(c.methods.stream().noneMatch(m->m.name.equals("onHitEntity")&&m.desc.equals("(Lcom/tacz/guns/util/TacHitResult;Lnet/minecraft/world/phys/Vec3;Lnet/minecraft/world/phys/Vec3;)V")))throw new Exception("TACZ target mismatch");if(c.fields.stream().noneMatch(f->f.name.equals("pierce")&&f.desc.equals("I")))throw new Exception("TACZ penetration field mismatch");}try(ZipFile z=new ZipFile(a[2])){ClassNode c=new ClassNode();new ClassReader(z.getInputStream(z.getEntry("ichttt/mods/firstaid/survival/CriticalCare.class"))).accept(c,0);if(c.methods.stream().noneMatch(m->m.name.equals("bite")&&m.desc.equals("(Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;Ljava/lang/Object;)V")))throw new Exception("FirstAid bite target mismatch");}System.out.println("Gore bytecode methods: "+methods+"; TACZ and FirstAid hooks matched");}}
